<script setup lang="ts">
import { UiButton } from '@/ui/base'
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import type { Member, MemberAction } from '@/types/enterprise'
import { useEnterpriseStore } from '@/stores/enterprise'
import AvatarMark from '@/ui/common/AvatarMark.vue'
import StatusBadge from '@/ui/common/StatusBadge.vue'
import AppIcon from '@/ui/common/AppIcon.vue'
import MemberRoleTags from './MemberRoleTags.vue'
import MemberDetailOverview from './MemberDetailOverview.vue'
import { backendTermLabel } from '@/i18n/backend-terms'
const props=defineProps<{member:Member|null;canEdit?:boolean;canChangeRoles?:boolean;canMore?:boolean}>(),emit=defineEmits<{close:[];action:[action:MemberAction,member:Member];more:[member:Member]}>(),store=useEnterpriseStore(),{t}=useI18n()
const tabs=['basic','roles','scope','logs'] as const; type Tab=(typeof tabs)[number]; const tab=ref<Tab>('basic'),panel=ref<HTMLElement>(),mobile=ref(false),memberLogs=computed(()=>store.logs.filter(log=>log.target===props.member?.name)); let trigger:HTMLElement|null=null,rootWasInert=false,inertOwned=false
const tabLabel=(item:Tab)=>t(`members.detail.${item}`)
const statusLabel=(status:Member['status'])=>t(`members.statuses.${status}`)
const scopeLabel=(scope:Member['scope'])=>t(`members.scopes.${scope==='department_tree'?'department':scope==='self'?'own':scope}`)
function setInert(){const root=document.getElementById('app');if(!root)return;if(props.member&&mobile.value){if(!inertOwned)rootWasInert=root.inert;root.inert=true;inertOwned=true}else if(inertOwned){root.inert=rootWasInert;inertOwned=false}}
function resize(){mobile.value=window.innerWidth<1280;setInert()}
function keydown(event:KeyboardEvent){if(!props.member)return;if(event.key==='Escape'){event.stopPropagation();emit('close')}if(event.key==='Tab'&&mobile.value){const items=panel.value?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],[tabindex="0"]');if(!items?.length)return;const first=items[0]!,last=items[items.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}
function moveTab(event:KeyboardEvent,index:number){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab.value=tabs[next]!;void nextTick(()=>panel.value?.querySelectorAll<HTMLElement>('[role="tab"]')[next]?.focus())}
watch(()=>props.member?.id,async(id,old)=>{if(id){if(!old)trigger=document.activeElement as HTMLElement;tab.value='basic';resize();await nextTick();panel.value?.querySelector<HTMLElement>('[data-close-detail]')?.focus()}else{setInert();await nextTick();if(trigger?.isConnected)trigger.focus()}})
onMounted(()=>{resize();window.addEventListener('resize',resize);document.addEventListener('keydown',keydown)});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);document.removeEventListener('keydown',keydown);const root=document.getElementById('app');if(root&&inertOwned)root.inert=rootWasInert})
</script>
<template>
  <Teleport to="body"><Transition name="detail-backdrop"><UiButton v-if="member&&mobile" class="member-detail-backdrop" tabindex="-1" :aria-label="t('members.detail.close')" @click="emit('close')"/></Transition><Transition name="member-detail"><aside v-if="member" id="member-detail-panel" ref="panel" class="member-detail-panel" role="dialog" :aria-modal="mobile" aria-labelledby="member-detail-title"><header class="detail-header"><h2 id="member-detail-title">{{ t('members.detail.title') }}</h2><UiButton class="icon-button" data-close-detail :aria-label="t('members.detail.close')" @click="emit('close')"><AppIcon name="close" :size="18"/></UiButton></header><div class="detail-scroll"><div class="detail-profile"><AvatarMark :name="member.name" :size="46" tone="solid"/><div class="detail-profile-copy"><div class="profile-title"><h2>{{ member.name }}</h2><StatusBadge :text="statusLabel(member.status)" :tone="member.status==='active'?'success':member.status==='suspended'?'danger':'neutral'"/></div><MemberRoleTags :ids="member.roleIds"/></div><div class="profile-actions"><UiButton v-if="canEdit" class="btn" :aria-label="t('members.editMember',{name:member.name})" @click="emit('action','edit',member)"><AppIcon name="edit" :size="13"/>{{ t('members.detail.edit') }}</UiButton><UiButton v-if="canMore" class="btn more-button" :aria-label="t('members.detail.more')" @click="emit('more',member)"><AppIcon name="more" :size="15"/></UiButton></div></div>
    <div class="detail-tabs" role="tablist" :aria-label="t('members.detail.tabsAria')"><UiButton v-for="(item,index) in tabs" :id="`detail-tab-${index}`" :key="item" :class="{active:tab===item}" role="tab" :aria-selected="tab===item" :tabindex="tab===item?0:-1" aria-controls="member-tab-content" @click="tab=item" @keydown="moveTab($event,index)">{{ tabLabel(item) }}</UiButton></div>
    <div id="member-tab-content" role="tabpanel" :aria-labelledby="`detail-tab-${tabs.indexOf(tab)}`" tabindex="0"><MemberDetailOverview v-if="tab==='basic'" :member="member" @logs="tab='logs'"/><div v-else-if="tab==='roles'" class="tab-body"><div class="row-between"><h3>{{ t('members.detail.assignedRoles') }}</h3><UiButton v-if="canChangeRoles" class="btn-link" @click="emit('action','role',member)">{{ t('members.detail.adjustRoles') }}</UiButton></div><article v-for="role in store.roles.filter(r=>member!.roleIds.includes(r.id))" :key="role.id" class="permission-section"><MemberRoleTags :ids="[role.id]"/><p>{{ role.description }}</p><ul><li v-for="permission in role.permissions" :key="permission"><AppIcon name="check" :size="13"/>{{ backendTermLabel('permission', permission) }}</li></ul></article></div><div v-else-if="tab==='scope'" class="tab-body"><div class="row-between"><h3>{{ t('members.detail.currentScope') }}</h3><UiButton v-if="canChangeRoles" class="btn-link" @click="emit('action','role',member)">{{ t('members.detail.adjustScope') }}</UiButton></div><div class="scope-summary"><AppIcon name="database" :size="24"/><div><strong>{{ scopeLabel(member.scope) }}</strong><p>{{ store.departmentName(member.departmentId) }}</p></div></div><p class="secondary">{{ t('members.detail.scopeExplanation') }}</p><div class="notice-box">{{ store.previewMode?t('members.detail.previewPermission'):t('members.detail.serverPermission') }}</div></div><div v-else class="tab-body"><h3>{{ t('members.detail.operationLogs') }}</h3><ol v-if="memberLogs.length" class="audit-list"><li v-for="log in memberLogs" :key="log.id"><strong>{{ log.action }}</strong><small>{{ log.time }} · {{ log.actor }}</small><p>{{ log.reason||t('members.detail.previewAction') }}</p></li></ol><div v-else class="detail-empty"><AppIcon name="file" :size="32"/><strong>{{ t('members.detail.noLogs') }}</strong><p>{{ t('members.detail.noLogsDetail') }}</p></div></div></div></div><footer class="detail-footer"><AppIcon name="shield" :size="13"/>{{ t('members.detail.footer') }}</footer></aside></Transition></Teleport>
</template>
<style scoped>
