20px 0;background:var(--color-success-soft);color:var(--color-success);border-radius:var(--radius-md);display:flex;gap:14px;align-items:center}.scope-summary p{font-size:11px;margin-top:4px}.tab-body .notice-box{margin-top:20px;font-size:12px}.detail-empty{display:flex;align-items:center;flex-direction:column;gap:12px;text-align:center;padding:42px 12px;color:var(--color-text-muted)}.audit-list{list-style:none;padding:0}.audit-list li{padding:15px 0;border-bottom:1px solid var(--color-border)}.audit-list small{display:block;margin:5px 0;color:var(--color-text-muted);font-size:11px}.audit-list p{color:var(--color-text-secondary)}.detail-footer{padding:10px 18px;flex-shrink:0;border-top:1px solid var(--color-border);display:flex;align-items:center;gap:6px;color:var(--color-text-muted);font-size:10px}.member-detail-enter-active,.member-detail-leave-active{transition:transform .24s cubic-bezier(.2,.8,.2,1),opacity .24s}.member-detail-enter-from,.member-detail-leave-to{transform:translateX(100%);opacity:0}.member-detail-backdrop{position:fixed;inset:var(--header-height) 0 0;z-index:calc(var(--z-member-detail) - 1);background:var(--color-overlay)}.detail-backdrop-enter-active,.detail-backdrop-leave-active{transition:opacity .2s}.detail-backdrop-enter-from,.detail-backdrop-leave-to{opacity:0}@media(max-width:767px){.member-detail-panel{top:0;width:100%;z-index:var(--z-dialog)}.member-detail-backdrop{inset:0}.detail-scroll{padding:0 22px}}@media(prefers-reduced-motion:reduce){.member-detail-enter-active,.member-detail-leave-active,.detail-backdrop-enter-active,.detail-backdrop-leave-active{transition:none}}
